    ```javascript
    // server/index.js
    const express = require('express');
    const cors = require('cors');
    const bodyParser = require('body-parser');
    const fs = require('fs');
    const path = require('path');

    const app = express();
    const PORT = 5000;
    const DATA_FILE = path.join(__dirname, 'data.json');

    // Middleware
    app.use(cors());
    app.use(bodyParser.json());

    // Helper to read data
    const getItems = () => {
        if (!fs.existsSync(DATA_FILE)) {
            return [];
        }
        return JSON.parse(fs.readFileSync(DATA_FILE, 'utf-8'));
    };

    // Helper to write data
    const saveItems = (items) => {
        fs.writeFileSync(DATA_FILE, JSON.stringify(items, null, 2));
    };

    // API Routes

    // 1. Get All Items (Read)
    app.get('/api/items', (req, res) => {
        const items = getItems();
        res.json(items);
    });

    // 2. Create Item (Create)
    app.post('/api/items', (req, res) => {
        const newItems = req.body;
        const items = getItems();
        newItems.id = Date.now(); // simple unique ID generation
        items.push(newItems);
        saveItems(items);
        res.status(201).json(newItems);
    });

    // 3. Delete Item (Delete)
    app.delete('/api/items/:id', (req, res) => {
        const items = getItems();
        const filteredItems = items.filter(item => item.id !== parseInt(req.params.id));
        saveItems(filteredItems);
        res.json({ message: 'Item deleted', items: filteredItems });
    });

    // Start Server
    app.listen(PORT, () => {
        console.log(`Server is running on http://localhost:${PORT}`);
    });
    ```

