This is a classic problem: making a "globally accessible" popup in React that doesn't rely on its immediate parent being open.

The solution is to create a **Global Tooltip Context**. The context will hold the state (`isOpen` and `targetElement`), and a provider component will render the actual tooltip at the root of the application, ensuring it is always available to trigger.

Here is a complete, copy-pasteable solution using Next.js (App Router) and Tailwind CSS.

### Step 1: Create the Context Provider
Create a file named `context/TooltipContext.tsx`. This is the brain. It uses `useState` to determine if the tooltip is open and *where* it should be positioned (we need to know the target element's coordinates).

```tsx
'use client';

import React, { createContext, useContext, useState, ReactNode, useRef, useEffect } from 'react';

interface TooltipContextType {
  openTooltip: (element: HTMLElement) => void;
  closeTooltip: () => void;
}

const TooltipContext = createContext<TooltipContextType | undefined>(undefined);

interface TooltipProviderProps {
  children: ReactNode;
}

export function TooltipProvider({ children }: TooltipProviderProps) {
  const [isOpen, setIsOpen] = useState(false);
  const [anchor, setAnchor] = useState<DOMRect | null>(null);
  const ref = useRef<HTMLDivElement>(null);

  const openTooltip = (element: HTMLElement) => {
    // 1. First, close the old one immediately
    if (isOpen) {
      setIsOpen(false);
      // Wait for a brief moment before opening the new one to avoid flickering
      setTimeout(() => {
        setAnchor(element.getBoundingClientRect());
        setIsOpen(true);
      }, 10); 
    } else {
      setAnchor(element.getBoundingClientRect());
      setIsOpen(true);
    }
  };

  const closeTooltip = () => {
    setIsOpen(false);
  };

  // Helper to close if clicking outside
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (isOpen && ref.current && !ref.current.contains(event.target as Node)) {
        closeTooltip();
      }
    };

    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, [isOpen]);

  return (
    <TooltipContext.Provider value={{ openTooltip, closeTooltip }}>
      {children}
      {/* The actual Tooltip is rendered here at the root level */}
      {isOpen && anchor && (
        <div 
          ref={ref}
          style={{
            position: 'fixed', // Fixed relative to the browser window, not the DOM
            left: anchor.left + 'px',
            top: (anchor.bottom + 8) + 'px', // Offset by 8px
          }}
          className="z-50 max-w-[300px] px-3 py-2 bg-gray-900 text-white text-sm rounded shadow-xl animate-in fade-in zoom-in duration-200"
        >
          {children}
        </div>
      )}
    </TooltipContext.Provider>
  );
}

export const useTooltip = () => {
  const context = useContext(TooltipContext);
  if (!context) {
    throw new Error('useTooltip must be used within a TooltipProvider');
  }
  return context;
};
```

